import csv
from collections import defaultdict

# PPCI: The claim is 'bias from 0.179 to 0.007 (R-learner)'
# R-learner is not a method in this file. Maybe it refers to the naive method in DGP B or C
# where naive_bias ~ 0.151 and ppci_bias ~ 0.025
# Or perhaps the paper references a different file or aggregation

# Let's check the specific value 0.179 more carefully
# naive_forest in CausalForest extreme = 0.17985 which is ~0.179!
# And ec_hte_forest extreme, n=500 has low bias

# Check PPCI for specific conditions matching 0.179 -> 0.007
with open('/home/ubuntu/ec_hte_llm_annotation/results/exp007_ppci_dsl.csv') as f:
    reader = csv.DictReader(f)
    rows = list(reader)

# Let's look at naive vs ppci in the C_both_errors DGP
print('=== DGP C_both_errors, extreme regime ===')
for m in ['naive', 'ppci', 'ec_hte_ppci', 'ec_hte']:
    vals = []
    for r in rows:
        if r['dgp'] == 'C_both_errors' and r['regime'] == 'extreme' and r['method'] == m:
            vals.append(abs(float(r['bias_z0'])))
            vals.append(abs(float(r['bias_z1'])))
    if vals:
        print(f'{m}: mean_abs_bias={sum(vals)/len(vals):.6f}, n={len(vals)}')

# Maybe across B and C combined
print()
print('=== DGP B+C combined ===')
for m in ['naive', 'ppci', 'ec_hte_ppci', 'ec_hte']:
    vals = []
    for r in rows:
        if r['dgp'] in ['B_outcome_only', 'C_both_errors'] and r['method'] == m:
            vals.append(abs(float(r['bias_z0'])))
            vals.append(abs(float(r['bias_z1'])))
    if vals:
        print(f'{m}: mean_abs_bias={sum(vals)/len(vals):.6f}, n={len(vals)}')

# The 0.179 from CausalForest (naive_forest extreme) and 0.007 for ppci
# Check if ppci has any aggregation ~ 0.007
print()
print('=== PPCI method, DGP D_no_error ===')
vals = []
for r in rows:
    if r['dgp'] == 'D_no_error' and r['method'] == 'ppci':
        vals.append(abs(float(r['bias_z0'])))
        vals.append(abs(float(r['bias_z1'])))
if vals:
    print(f'ppci D_no_error: mean_abs_bias={sum(vals)/len(vals):.6f}, n={len(vals)}')

# Check ec_hte_ppci overall
print()
print('=== ec_hte_ppci across all DGPs ===')
for dgp in ['A_covariate_only', 'B_outcome_only', 'C_both_errors', 'D_no_error']:
    vals = []
    for r in rows:
        if r['dgp'] == dgp and r['method'] == 'ec_hte_ppci':
            vals.append(abs(float(r['bias_z0'])))
            vals.append(abs(float(r['bias_z1'])))
    if vals:
        print(f'  {dgp}: mean_abs_bias={sum(vals)/len(vals):.6f}, n={len(vals)}')

# Check if there's any method with bias ~0.007 in ppci data
print()
for m in sorted(set(r['method'] for r in rows)):
    for dgp in sorted(set(r['dgp'] for r in rows)):
        for regime in sorted(set(r['regime'] for r in rows)):
            for n in sorted(set(r['n_expert'] for r in rows)):
                vals = []
                for r in rows:
                    if r['method'] == m and r['dgp'] == dgp and r['regime'] == regime and r['n_expert'] == n:
                        vals.append(abs(float(r['bias_z0'])))
                        vals.append(abs(float(r['bias_z1'])))
                if vals:
                    mean_v = sum(vals)/len(vals)
                    if abs(mean_v - 0.007) < 0.002:
                        print(f'~0.007: {m}, {dgp}, {regime}, n={n}: {mean_v:.6f}')
                    if abs(mean_v - 0.179) < 0.005:
                        print(f'~0.179: {m}, {dgp}, {regime}, n={n}: {mean_v:.6f}')
"
